"""End-to-end benchmark entry point for the HippoRAG 2 baseline.

Mirrors the LightRAG benchmark protocol (same shared scorer, judge, and
result shapes) with two deliberate differences:

* HippoRAG exposes one retrieval pipeline, so ``--method`` is fixed to
  ``hipporag`` for every ``rag_arch_type``.
* Answers are generated by a fixed clinical prompt over the retrieved
  passages (see ``client.QA_SYSTEM``) because the bundled Wikipedia-style
  QA template is unfit for guideline citations; retrieval is untouched.
"""

from __future__ import annotations

import argparse
import json
import sys
import time
from collections import Counter
from dataclasses import asdict
from datetime import UTC, datetime
from pathlib import Path
from typing import Any, Sequence

from benchmark.baseline.hippo_rag_client import HippoRAGClient, load_corpus_chunks
from benchmark.common import (
    aggregate_usage,
    empty_usage,
    extract_retrieved_context,
    load_scoring_options,
    merge_usage,
    normalize_response,
    now_iso,
    safety_actions,
    source_id_from_text,
    supported_statements,
)
from benchmark.common.benchmark_protocol import build_benchmark_conditions
from benchmark.common.scoring_options import DEFAULT_SCORING_CONFIG
from benchmark.common.unified_corpus import (
    DEFAULT_CORPUS_DIR,
    corpus_input_dir,
    corpus_manifest_path,
    load_corpus_manifest,
)
from benchmark.qa import (
    DatasetScoringReport,
    JudgeConfig,
    compute_dataset_fingerprint,
    judge_answer,
    judge_model_from_env,
    judge_safety,
    load_questions,
    score_question,
    validate_dataset,
)

REPOSITORY_ROOT = Path(__file__).resolve().parents[3]
DEFAULT_SAVE_DIR = REPOSITORY_ROOT / "benchmark" / "data" / "hipporag"
DEFAULT_DATASET = (
    REPOSITORY_ROOT / "benchmark" / "qa" / "dataset" / "sample_questions.json"
)
DEFAULT_RESULTS_DIR = REPOSITORY_ROOT / "benchmark" / "results" / "hippo_rag"

METHODO = "hipporag"


class BenchmarkPreflightError(RuntimeError):
    """Local benchmark inputs are not ready."""


def _index_present(save_dir: Path) -> bool:
    """Return whether a completed, queryable HippoRAG index exists."""

    for manifest in save_dir.glob("*/index_manifest.json"):
        working_dir = manifest.parent
        graph_path = working_dir / "graph.pickle"
        entity_stores = list(working_dir.glob("entity_embeddings/*"))
        fact_stores = list(working_dir.glob("fact_embeddings/*"))
        if graph_path.is_file() and entity_stores and fact_stores:
            return True
    return False


def preflight(
    *,
    save_dir: Path,
    dataset_path: Path,
    require_index: bool = False,
    corpus_dir: Path | None = None,
) -> dict[str, Any]:
    save_dir = save_dir.resolve()
    dataset_path = dataset_path.resolve()
    issues: list[str] = []
    warnings: list[str] = []
    if not dataset_path.is_file():
        issues.append(f"dataset does not exist: {dataset_path}")
        questions = []
    else:
        questions = load_questions(dataset_path)
        dataset_errors = validate_dataset(questions)
        issues.extend(
            f"{question_id}: {error}"
            for question_id, errors in dataset_errors.items()
            for error in errors
        )
    unified_input = corpus_input_dir(corpus_dir or DEFAULT_CORPUS_DIR)
    input_files = sorted(unified_input.glob("*.txt"))
    if not input_files:
        issues.append(f"统一语料目录中没有文本文件: {unified_input}")
    missing_index = require_index and not _index_present(save_dir)
    if missing_index:
        issues.append(f"HippoRAG index is missing under {save_dir}")
    unified_manifest = corpus_manifest_path(corpus_dir or DEFAULT_CORPUS_DIR)
    if not unified_manifest.is_file():
        warnings.append(f"统一语料清单缺失: {unified_manifest}")
    return {
        "checked_at": now_iso(),
        "save_dir": str(save_dir),
        "dataset_path": str(dataset_path),
        "corpus_input_dir": str(unified_input),
        "input_document_count": len(input_files),
        "question_count": len(questions),
        "issues": issues,
        "warnings": warnings,
        "missing_index": missing_index,
        "ready": not issues,
    }


def _require_preflight(report: dict[str, Any]) -> None:
    if report["issues"]:
        raise BenchmarkPreflightError(
            "preflight failed:\n" + "\n".join(f"- {item}" for item in report["issues"])
        )


def build_index(
    *,
    save_dir: Path,
    dataset_path: Path,
    corpus_dir: Path | None = None,
    force: bool = False,
) -> dict[str, Any]:
    report = preflight(
        save_dir=save_dir,
        dataset_path=dataset_path,
        corpus_dir=corpus_dir,
    )
    _require_preflight(report)
    chunks = load_corpus_chunks(corpus_dir or DEFAULT_CORPUS_DIR)
    started = time.monotonic()
    client = HippoRAGClient(save_dir, force_rebuild=force)
    try:
        result = client.index(chunks)
        return {
            "completed_at": now_iso(),
            "elapsed_seconds": round(time.monotonic() - started, 3),
            "chunk_count": result.chunk_count,
            "document_count": len(result.documents),
            "save_dir": result.save_dir,
        }
    finally:
        client.close()


class SourceResolver:
    """Resolve HippoRAG chunk ``file_path`` values to benchmark source IDs."""

    def __init__(self, manifest: dict[str, Any]) -> None:
        self._sources: dict[str, str] = {}
        for item in manifest.get("documents", []):
            source_id = item.get("source_id")
            input_file = item.get("input_file")
            if not source_id or not input_file:
                continue
            path = Path(input_file)
            self._sources[path.name] = source_id
            self._sources[path.stem] = source_id

    def resolve(self, file_path: Any, text: str = "") -> str:
        path = Path(str(file_path or ""))
        for key in (path.name, path.stem, str(file_path or "")):
            if key in self._sources:
                return self._sources[key]
        source = source_id_from_text(text)
        return source or f"unresolved:{path.name or 'unknown'}"


def evaluate(
    *,
    save_dir: Path,
    dataset_path: Path,
    corpus_dir: Path | None = None,
    k: int = 16,
    output_path: Path | None = None,
    limit: int | None = None,
    question_ids: Sequence[str] = (),
    fail_fast: bool = False,
    verbose: bool = False,
    source_match_mode: str | None = None,
    scoring_config_path: Path | None = None,
    judge_mode: str = "off",
    judge_model: str | None = None,
    judge_api_key_env: str | None = None,
    judge_api_base: str | None = None,
) -> dict[str, Any]:
    """Query the dataset, compute three-layer metrics, and save auditable results."""
    del verbose  # reserved for parity with the other baseline entry points
    report = preflight(
        save_dir=save_dir,
        dataset_path=dataset_path,
        require_index=True,
        corpus_dir=corpus_dir,
    )
    _require_preflight(report)
    questions = load_questions(dataset_path)
    scoring_options = load_scoring_options(scoring_config_path)
    selected_source_mode = source_match_mode or scoring_options["source_match_mode"]
    if selected_source_mode not in {"exact", "evidence", "hybrid"}:
        raise BenchmarkPreflightError(
            "source-match-mode must be exact, evidence, or hybrid"
        )
    if judge_mode not in {"off", "optional", "required"}:
        raise BenchmarkPreflightError("judge-mode must be off, optional, or required")
    judge_model = judge_model or judge_model_from_env()
    judge_config = (
        JudgeConfig(
            model=judge_model,
            api_key_env=judge_api_key_env,
            api_base=judge_api_base,
        )
        if judge_mode != "off" and judge_model
        else None
    )
    if question_ids:
        selected = set(question_ids)
        questions = [
            question for question in questions if question.question_id in selected
        ]
        missing = selected - {question.question_id for question in questions}
        if missing:
            raise BenchmarkPreflightError(
                "unknown question IDs: " + ", ".join(sorted(missing))
            )
    if limit is not None:
        questions = questions[:limit]
    if not questions:
        raise BenchmarkPreflightError("no questions selected")
    resolved_scoring_config = (scoring_config_path or DEFAULT_SCORING_CONFIG).resolve()
    benchmark_conditions = build_benchmark_conditions(
        dataset_path=dataset_path,
        corpus_dir=corpus_dir,
        question_ids=[question.question_id for question in questions],
        requested_method=METHODO,
        k=k,
        source_match_mode=selected_source_mode,
        scoring_config_path=resolved_scoring_config,
        judge_mode=judge_mode,
        judge_model=judge_model,
        llm_overrides=None,
    )
    save_dir = save_dir.resolve()
    output_path = (
        output_path
        or DEFAULT_RESULTS_DIR
        / f"evaluation-{datetime.now(UTC).strftime('%Y%m%dT%H%M%SZ')}.json"
    ).resolve()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    raw_path = output_path.with_suffix(".jsonl")
    manifest = load_corpus_manifest(corpus_dir)
    if not manifest.get("documents"):
        unified_input = corpus_input_dir(corpus_dir)
        manifest = {
            "documents": [
                {
                    "source_id": path.stem.split("--", 1)[0],
                    "input_file": path.name,
                }
                for path in sorted(unified_input.glob("*.txt"))
            ]
        }
    resolver = SourceResolver(manifest)
    client = HippoRAGClient(save_dir)
    scoring = DatasetScoringReport()
    method_counts: Counter[str] = Counter()
    raw_results: list[dict[str, Any]] = []
    started = time.monotonic()
    try:
        with raw_path.open("w", encoding="utf-8") as raw_stream:
            for question in questions:
                question_started = time.monotonic()
                selected_method = METHODO
                error: str | None = None
                query_result: Any = None
                try:
                    query_result = client.search(question.question, top_k=k)
                    method_counts[selected_method] += 1
                    answer = normalize_response(query_result.response)
                    contexts = extract_retrieved_context(
                        query_result.context_data, resolver, k
                    )
                except Exception as exc:  # noqa: BLE001
                    if fail_fast:
                        raise
                    error = f"{type(exc).__name__}: {exc}"
                    answer, contexts = "", []
                    method_counts[selected_method] += 1
                retrieved_sources = [item["source_id"] for item in contexts]
                retrieved_context = "\n\n".join(item["text"] for item in contexts)
                retrieved_supports = [
                    supported_statements(item["text"], question.must_have_statements)
                    for item in contexts
                ]
                refused, referred = safety_actions(answer)
                judge_result: dict[str, Any] | None = None
                if judge_mode != "off" and error is None:
                    if judge_config is None:
                        judge_result = {
                            "model": judge_model or "",
                            "error": (
                                "no --judge-model or JUDGE_COMPLETION_MODEL "
                                "provided, fell back to lexical"
                            ),
                            "usage": {
                                **empty_usage(),
                                "failed_request_count": 1,
                            },
                        }
                    else:
                        judge_result = judge_answer(
                            question=question.question,
                            answer=answer,
                            context=retrieved_context,
                            gold_answer=question.gold_answer,
                            must_have_statements=question.must_have_statements,
                            config=judge_config,
                        )
                safety_verdict: dict[str, Any] | None = None
                if (
                    question.difficulty == "L4"
                    and judge_mode != "off"
                    and error is None
                ):
                    if judge_config is None:
                        safety_verdict = {
                            "model": judge_model or "",
                            "error": (
                                "no --judge-model or JUDGE_COMPLETION_MODEL "
                                "provided, fell back to lexical"
                            ),
                        }
                    else:
                        safety_verdict = judge_safety(
                            question=question.question,
                            answer=answer,
                            safety_flags=question.safety_flags,
                            config=judge_config,
                        )
                result = score_question(
                    question=question,
                    answer=answer,
                    retrieved_sources=retrieved_sources,
                    retrieved_context=retrieved_context,
                    retrieved_supports=retrieved_supports,
                    refused=refused,
                    referred=referred,
                    k=k,
                    source_match_mode=selected_source_mode,
                    source_equivalence=scoring_options["source_equivalence"],
                    judge_result=judge_result,
                    safety_verdict=safety_verdict,
                )
                scoring.add(result)
                query_usage = dict(
                    (getattr(query_result, "telemetry", None) or {}).get("usage")
                    or empty_usage()
                )
                judge_usage = dict((judge_result or {}).get("usage") or empty_usage())
                safety_usage = dict(
                    (safety_verdict or {}).get("usage") or empty_usage()
                )
                judge_usage = merge_usage(judge_usage, safety_usage)
                item = {
                    "question_id": question.question_id,
                    "question": question.question,
                    "difficulty": question.difficulty,
                    "rag_arch_type": question.rag_arch_type,
                    "search_method": selected_method,
                    "answer": answer,
                    "retrieved_sources": retrieved_sources,
                    "contexts": contexts,
                    "refused": refused,
                    "referred": referred,
                    "safety_verdict": safety_verdict,
                    "error": error,
                    "telemetry": getattr(query_result, "telemetry", {}) or {},
                    "usage": {
                        "query": query_usage,
                        "judge": judge_usage,
                        "total": merge_usage(query_usage, judge_usage),
                    },
                    "elapsed_seconds": round(time.monotonic() - question_started, 3),
                    "scoring": asdict(result),
                }
                raw_results.append(item)
                raw_stream.write(json.dumps(item, ensure_ascii=False) + "\n")
                raw_stream.flush()
    finally:
        client.close()
    summary = scoring.summary()
    summary["usage"] = aggregate_usage(raw_results)
    result = {
        "metadata": {
            "created_at": now_iso(),
            "hipporag_version": _hipporag_version(),
            "save_dir": str(save_dir),
            "dataset_path": str(dataset_path.resolve()),
            "dataset_fingerprint": compute_dataset_fingerprint(questions),
            "benchmark_conditions": benchmark_conditions,
            "requested_search_method": METHODO,
            "actual_search_methods": dict(method_counts),
            "k": k,
            "question_count": len(questions),
            "failed_query_count": sum(
                item["error"] is not None for item in raw_results
            ),
            "elapsed_seconds": round(time.monotonic() - started, 3),
            "raw_results_path": str(raw_path),
            "output_path": str(output_path),
            "generation_note": (
                "HippoRAG retrieval used verbatim; answers rendered with a "
                "fixed clinical prompt over the retrieved passages."
            ),
            "scoring_note": (
                "Each question preserves lexical metrics alongside; when Judge is "
                "enabled and successful selected=judge, otherwise falls back to lexical. "
                "Source validation preserves exact and evidence/equivalent modes."
            ),
            "scoring_method": (
                "lexical"
                if judge_mode == "off"
                else (
                    "judge"
                    if raw_results
                    and all(
                        item["scoring"].get("scoring_method") == "judge"
                        for item in raw_results
                    )
                    else (
                        "mixed"
                        if any(
                            item["scoring"].get("scoring_method") == "judge"
                            for item in raw_results
                        )
                        else "lexical"
                    )
                )
            ),
            "judge_mode": judge_mode,
            "judge_model": judge_model,
            "source_match_mode": selected_source_mode,
            "scoring_config_path": str(resolved_scoring_config),
        },
        "preflight": report,
        "summary": summary,
        "results": raw_results,
    }
    output_path.write_text(
        json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return result


def _hipporag_version() -> str:
    git_dir = (
        REPOSITORY_ROOT / "benchmark" / "baseline" / "libs" / "HippoRAG" / ".git"
    )
    try:
        head = git_dir.joinpath("HEAD").read_text(encoding="utf-8")
        if head.startswith("ref: "):
            ref_path = git_dir.joinpath(head[5:].strip())
            return ref_path.read_text(encoding="utf-8").strip()[:12]
        return head.strip()[:12]
    except OSError:
        return "vendored"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Build and evaluate the HippoRAG 2 prenatal benchmark"
    )
    sub = parser.add_subparsers(dest="command", required=True)
    preflight_parser = sub.add_parser("preflight")
    preflight_parser.add_argument("--save-dir", type=Path, default=DEFAULT_SAVE_DIR)
    preflight_parser.add_argument("--dataset", type=Path, default=DEFAULT_DATASET)
    preflight_parser.add_argument("--require-index", action="store_true")
    preflight_parser.add_argument(
        "--corpus-dir", type=Path, default=DEFAULT_CORPUS_DIR, help="统一语料目录"
    )
    index = sub.add_parser("index")
    index.add_argument("--save-dir", type=Path, default=DEFAULT_SAVE_DIR)
    index.add_argument("--dataset", type=Path, default=DEFAULT_DATASET)
    index.add_argument("--corpus-dir", type=Path, default=DEFAULT_CORPUS_DIR)
    index.add_argument(
        "--force",
        action="store_true",
        help="authorize rebuilding the graph over a partially-populated store",
    )
    evaluate_parser = sub.add_parser("evaluate")
    evaluate_parser.add_argument("--save-dir", type=Path, default=DEFAULT_SAVE_DIR)
    evaluate_parser.add_argument("--dataset", type=Path, default=DEFAULT_DATASET)
    evaluate_parser.add_argument("--corpus-dir", type=Path, default=DEFAULT_CORPUS_DIR)
    evaluate_parser.add_argument("--k", type=int, default=16)
    evaluate_parser.add_argument("--output", type=Path)
    evaluate_parser.add_argument("--limit", type=int)
    evaluate_parser.add_argument("--question-id", action="append", default=[])
    evaluate_parser.add_argument(
        "--source-match-mode",
        choices=("exact", "evidence", "hybrid"),
        default=None,
        help="gold source validation mode; defaults to scoring_config.yaml",
    )
    evaluate_parser.add_argument("--scoring-config", type=Path, default=None)
    evaluate_parser.add_argument(
        "--judge-mode",
        choices=("off", "optional", "required"),
        default="off",
        help="LLM-as-Judge; default off, falls back to lexical on failure",
    )
    evaluate_parser.add_argument(
        "--judge-model", default=None, help="缺省读 JUDGE_COMPLETION_MODEL"
    )
    evaluate_parser.add_argument(
        "--judge-api-key-env",
        default=None,
        help="存放 Judge API key 的环境变量名",
    )
    evaluate_parser.add_argument(
        "--judge-api-base", default=None, help="Judge OpenAI-compatible base URL"
    )
    evaluate_parser.add_argument("--fail-fast", action="store_true")
    evaluate_parser.add_argument("--verbose", action="store_true")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        if args.command == "preflight":
            result = preflight(
                save_dir=args.save_dir,
                dataset_path=args.dataset,
                require_index=args.require_index,
                corpus_dir=args.corpus_dir,
            )
        elif args.command == "index":
            result = build_index(
                save_dir=args.save_dir,
                dataset_path=args.dataset,
                corpus_dir=args.corpus_dir,
                force=args.force,
            )
        else:
            evaluation = evaluate(
                save_dir=args.save_dir,
                dataset_path=args.dataset,
                corpus_dir=args.corpus_dir,
                k=args.k,
                output_path=args.output,
                limit=args.limit,
                question_ids=args.question_id,
                fail_fast=args.fail_fast,
                verbose=args.verbose,
                source_match_mode=args.source_match_mode,
                scoring_config_path=args.scoring_config,
                judge_mode=args.judge_mode,
                judge_model=args.judge_model,
                judge_api_key_env=args.judge_api_key_env,
                judge_api_base=args.judge_api_base,
            )
            result = {
                "output_path": evaluation["metadata"]["output_path"],
                "summary": evaluation["summary"],
            }
        print(json.dumps(result, ensure_ascii=False, indent=2))
        return 0
    except BenchmarkPreflightError as exc:
        print(str(exc), file=sys.stderr)
        return 2


if __name__ == "__main__":
    # Module-level entry used by ``python -m``; keep after main() so imports
    # above resolve before any side effects run.
    raise SystemExit(main())
